#!/usr/bin/env node
// Regenerates src/icons/brands.generated.ts and src/icons/fileTypeIcons.generated.ts from the
// simple-icons devDependency. Run this after editing BRAND_SLUGS or FILE_TYPE_SLUGS below — never
// hand-edit the generated files. simple-icons is CC0-licensed brand marks, kept as a devDependency only: nothing
// here ships at runtime except the tiny path+hex pairs baked into the generated file.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ICONS_DIR = path.join(__dirname, "..", "node_modules", "simple-icons", "icons");
const DATA_PATH = path.join(__dirname, "..", "node_modules", "simple-icons", "data", "simple-icons.json");
const OUT_DIR = path.join(__dirname, "..", "src", "icons");

// Curated external-system/actor brands actually present in the current simple-icons release —
// some well-known marks (AWS, Azure, Slack, OpenAI, Twilio, SendGrid) have been withdrawn from the
// package on trademark request and simply aren't available; unset/unknown slugs fall back to the
// generic external_system icon, so a missing brand degrades gracefully rather than erroring.
const BRAND_SLUGS = [
  "stripe",
  "paypal",
  "github",
  "gitlab",
  "bitbucket",
  "githubactions",
  "circleci",
  "googlecloud",
  "digitalocean",
  "render",
  "cloudflare",
  "vercel",
  "netlify",
  "postgresql",
  "mysql",
  "mariadb",
  "sqlite",
  "mongodb",
  "redis",
  "influxdb",
  "apachekafka",
  "rabbitmq",
  "docker",
  "kubernetes",
  "terraform",
  "nginx",
  "elasticsearch",
  "elastic",
  "grafana",
  "prometheus",
  "newrelic",
  "datadog",
  "sentry",
  "pagerduty",
  "anthropic",
  "auth0",
  "okta",
  "firebase",
  "supabase",
  "jira",
  "confluence",
  "figma",
  "zendesk",
  "hubspot",
];

// Language/tool logos for the Files panel's IDE-style file icons; fileTypes.ts maps names to these.
const FILE_TYPE_SLUGS = [
  "c",
  "cplusplus",
  "css",
  "dart",
  "docker",
  "dotenv",
  "dotnet",
  "editorconfig",
  "elixir",
  "eslint",
  "git",
  "gnubash",
  "go",
  "gradle",
  "graphql",
  "haskell",
  "html5",
  "javascript",
  "jest",
  "json",
  "jupyter",
  "kotlin",
  "less",
  "lua",
  "markdown",
  "mdx",
  "npm",
  "openjdk",
  "perl",
  "php",
  "pnpm",
  "poetry",
  "prettier",
  "prisma",
  "python",
  "r",
  "react",
  "ruby",
  "rust",
  "sass",
  "scala",
  "sqlite",
  "svelte",
  "svg",
  "swift",
  "terraform",
  "toml",
  "typescript",
  "vite",
  "vitest",
  "vuedotjs",
  "xml",
  "yaml",
  "yarn",
  "zig",
];

// Writes one generated icon table; `ownsType` emits the shared entry interface, `withTitle` keeps titles.
async function writeIconSet(bySlug, { slugs, listName, fileName, exportName, ownsType, withTitle }) {
  const entries = [];
  for (const slug of slugs) {
    const meta = bySlug.get(slug);
    if (!meta) throw new Error(`simple-icons has no entry for slug "${slug}" — check ${listName}`);
    const svg = await readFile(path.join(ICONS_DIR, `${slug}.svg`), "utf-8");
    const match = svg.match(/<path d="([^"]+)"/);
    if (!match) throw new Error(`could not extract path data from ${slug}.svg`);
    entries.push({ slug, title: meta.title, hex: meta.hex, path: match[1] });
  }
  entries.sort((a, b) => a.slug.localeCompare(b.slug));

  const body = entries
    .map((entry) => {
      const title = withTitle ? `title: ${JSON.stringify(entry.title)}, ` : "";
      return `  ${entry.slug}: { ${title}hex: ${JSON.stringify(entry.hex)}, path: ${JSON.stringify(entry.path)} },`;
    })
    .join("\n");

  const typeBlock = ownsType
    ? `export interface BrandIconEntry {
  title: string;
  hex: string;
  path: string;
}
`
    : `import type { BrandIconEntry } from "./brands.generated";
`;
  const entryType = withTitle ? "BrandIconEntry" : `Omit<BrandIconEntry, "title">`;

  const contents = `// Generated by scripts/update-brand-icons.mjs from the simple-icons package — do not hand-edit.
// To add an icon: append its slug to ${listName} in that script and rerun it.
${typeBlock}
export const ${exportName}: Record<string, ${entryType}> = {
${body}
};
`;
  const outPath = path.join(OUT_DIR, fileName);
  await writeFile(outPath, contents);
  console.log(`Wrote ${entries.length} icons to ${path.relative(process.cwd(), outPath)}`);
}

async function main() {
  const rawData = JSON.parse(await readFile(DATA_PATH, "utf-8"));
  const bySlug = new Map(rawData.map((entry) => [entry.slug, entry]));
  await writeIconSet(bySlug, {
    slugs: BRAND_SLUGS,
    listName: "BRAND_SLUGS",
    fileName: "brands.generated.ts",
    exportName: "BRAND_ICONS",
    ownsType: true,
    withTitle: true,
  });
  await writeIconSet(bySlug, {
    slugs: FILE_TYPE_SLUGS,
    listName: "FILE_TYPE_SLUGS",
    fileName: "fileTypeIcons.generated.ts",
    exportName: "FILE_TYPE_ICONS",
    ownsType: false,
    withTitle: false,
  });
}

main();
